ATL_SRC.push(['@atl/access.js', 0, `// Page access per user (Settings ▸ Users & roles ▸ Pages): an admin can hide pages from a user. The hidden pages
// leave that user's sidebar and open as "no access". Admins always see every page. What a user can read or change
// is still set by their role (firestore.rules); hiding a page is about what they are shown.
import { store } from '@atl/store.js';
import { canSee } from '@atl/sites.js';

/** Every page that can be hidden, as in the sidebar: [key (its address), label, group, matches(path)]. */
export const PAGES = [
  ['#/', 'Command Center', 'Overview', p => p === '/' || p === '' || p === '/home'],
  ['#/records', 'All records (list of every log)', 'Records'],
  ['#/dashboard/all', 'Dashboards (one per location they see, and Combined Atlanta)', 'Overview', p => p.startsWith('/dashboard')],
  ['#/scorecards', 'Scorecards: Attendance & Damage', 'Overview', p => p.startsWith('/scorecards')],
  ['#/electrolit', 'Electrolit customer scorecard', 'Overview'],
  ['#/westrock', 'Smurfit WestRock customer scorecard', 'Overview'],
  ['#/customers', 'Customer History (per-customer Billing Activity trends)', 'Overview'],
  ['#/rail', 'Rail & Demurrage', 'Overview', p => p === '/rail' || p.startsWith('/rail/')],
  ['#/mhe', 'MHE Fleet (equipment, maintenance, inspections, lockout / tagout, reports, operators)', 'Overview', p => p === '/mhe' || p.startsWith('/log/mhe')],
  ['#/training', 'Training (weekly / monthly meetings, tracker, supervisor scorecard)', 'Overview'],
  ['#/quality', 'Data Quality', 'Overview'],
  ['#/weekly', 'Weekly Entry', 'Weekly work'],
  ['#/log/otif', 'OTIF Log', 'Logs'],
  ['#/safety', 'Safety Incidents', 'Logs'],
  ['#/log/attendance', 'Attendance Log', 'Logs'],
  ['#/log/damage', 'Damage Log', 'Logs'],
  ['#/log/trucks', 'Truck Appointments', 'Logs'],
  ['#/log/elxNcr', 'Electrolit NCRs', 'Logs'],
  ['#/log/wrAcr', 'WestRock ACRs', 'Logs'],
  ['#/log/recognition', 'Recognition', 'Logs'],
  ['#/log/discipline', 'Disciplinary Log (managers and admins only)', 'Logs'],
  ['#/log/labor', 'Labor', 'Logs'],
  ['#/log/throughput', 'Customer Throughput', 'Logs'],
  ['#/log/opmoves', 'Operator Moves', 'Logs'],
  ['#/log/employees', 'Employees', 'Logs'],
  ['#/docs', 'SOP / Documents', 'Library'],
  ['#/archive', 'Sent Reports Archive', 'Library'],
];

const pathOf = h => h.slice(1).split('?')[0];
/** The page a path belongs to (its key), or '' when it isn't one that can be hidden. */
export function pageOf(path) {
  const p = PAGES.find(([key, , , match]) => (match ? match(path) : path === pathOf(key) || path.startsWith(pathOf(key) + '/')));
  return p ? p[0] : '';
}
/** Is this page hidden from the signed-in user? (Never for admins.) */
export const isHidden = keyOrPath => {
  if (store.can('admin')) return false;
  const path = keyOrPath.startsWith('#') ? pathOf(keyOrPath) : keyOrPath;
  if (!locationOk(path)) return true;
  if (!store.hidden?.length) return false;
  const key = pageOf(path);
  return !!key && store.hidden.includes(key);
};
// Pages that belong to one location (sites.js): Electrolit is a 6049 customer, Smurfit WestRock a 6021 customer, each
// rail customer has its building (Rail settings). Someone who doesn't see that location doesn't get the page.
function locationOk(path) {
  const p = decodeURIComponent(path || '');
  if (p === '/electrolit' || p === '/log/elxNcr') return canSee('6049');
  if (p === '/westrock' || p === '/log/wrAcr') return canSee('6021');
  const custs = store.rail?.customers || [];
  if (p.startsWith('/rail/')) { const c = custs.find(x => x.name === p.slice(6)); return !c || canSee(c.building); }
  if (p === '/rail') return !custs.length || custs.some(c => canSee(c.building));
  return true;
}`]);

