ATL_SRC.push(['@atl/forms/docx.js', 0, `// Small helpers for filling in an embedded Word template (.docx): find cells by their label, write text, tick ☐ boxes.
import { zip } from '@atl/util.js';

export const W = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main';
export const DOCX = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
const XML_NS = 'http://www.w3.org/XML/1998/namespace';
const b64 = s => Uint8Array.from(atob(s), c => c.charCodeAt(0));

/** PARTS = [[path, 'text' | 'b64', content]] → a function (fill(doc, helpers)) → Blob that builds a filled copy. */
export function docxBuilder(PARTS) {
  let parts;
  return fill => {
    parts ||= PARTS.map(([p, kind, c]) => [p, kind === 'b64' ? b64(c) : c]);
    return zip(parts.map(([p, c]) => [p, p === 'word/document.xml' ? edit(c, fill) : c]), DOCX);
  };
}

function edit(xml, fill) {
  const doc = new DOMParser().parseFromString(xml, 'application/xml');
  const all = (el, tag) => [...el.getElementsByTagNameNS(W, tag)];
  const text = el => all(el, 't').map(t => t.textContent).join('').trim();
  const up = (el, tag) => { while (el && !(el.namespaceURI === W && el.localName === tag)) el = el.parentNode; return el; };
  const el = (tag, attrs = {}) => { const e = doc.createElementNS(W, 'w:' + tag); for (const [k, v] of Object.entries(attrs)) e.setAttributeNS(W, 'w:' + k, v); return e; };
  const sib = tc => { let n = tc?.nextSibling; while (n && n.localName !== 'tc') n = n.nextSibling; return n; };
  const h = {
    doc, all, text, el,
    /** The table whose text starts with \`title\`. */
    table: title => up(all(doc, 'tc').find(tc => text(tc).startsWith(title)), 'tbl'),
    /** The cell right of the cell labelled \`label\` (inside \`scope\`). */
    after: (scope, label) => sib(all(scope, 'tc').find(c => text(c) === label)),
    /** Row \`n\` (0-based) first cell of a table — the text box under a section heading. */
    box: (tbl, n = 1) => tbl && all(tbl, 'tr')[n]?.getElementsByTagNameNS(W, 'tc')[0],
    /** Remove everything written in a cell (e.g. a grey placeholder). */
    clear: tc => { for (const p of all(tc || doc.createElement('x'), 'p')) for (const r of [...p.childNodes].filter(n => n.localName !== 'pPr')) r.remove(); },
    /** Write text into a cell; each line (array item or \\n) gets its own line. */
    put: (tc, lines, size = '20') => {
      if (!tc) return;
      const p = all(tc, 'p')[0];
      [].concat(lines).flatMap(l => String(l ?? '').split('\\n')).filter((l, i, a) => l || a.length > 1).forEach((line, i) => {
        const r = el('r'), rPr = el('rPr'); rPr.append(el('sz', { val: size }), el('szCs', { val: size })); r.append(rPr);
        if (i) r.append(el('br'));
        const t = el('t'); t.setAttributeNS(XML_NS, 'xml:space', 'preserve'); t.textContent = line; r.append(t); p.append(r);
      });
    },
    /** Tick "☐ Option" inside \`scope\`; \`replace\` swaps the option text, e.g. "☒ Other: night shift". */
    tick: (scope, option, replace) => {
      if (!scope || !option) return;
      const esc = option.replace(/[.*+?^\${}()|[\\]\\\\/]/g, '\\\\$&');
      const t = all(scope, 't').find(x => x.textContent.includes('☐ ' + option));
      if (!t) return;
      t.textContent = t.textContent.replace(new RegExp('☐ ' + esc + (replace ? '[^☐]*?(?=\\\\s{2,}|$)' : '')), replace ?? '☒ ' + option);
      // A blank line ("_____") kept in the next run(s) belongs to the replaced text — drop it.
      // (Word's spell-check and bookmark markers can sit between those runs; step over them.)
      if (replace) for (let r = t.parentNode.nextSibling; r; r = r.nextSibling) {
        if (['proofErr', 'bookmarkStart', 'bookmarkEnd'].includes(r.localName)) continue;
        if (r.localName !== 'r') break;
        const rt = r.getElementsByTagNameNS(W, 't')[0]; if (!rt || !/^_+\\s*$/.test(rt.textContent)) break;
        rt.textContent = rt.textContent.replace(/_+/, '');
      }
    },
  };
  fill(h);
  // ☐ / ☒ boxes have no font of their own in these templates, so Word substitutes one that draws them as tiny
  // asterisks. Put every box in its own run in Segoe UI Symbol (on every Windows PC) so they show as real boxes.
  for (const t of all(doc, 't').filter(x => /[☐☒]/.test(x.textContent))) {
    const r = t.parentNode, rPr = all(r, 'rPr')[0];
    for (const piece of t.textContent.split(/([☐☒])/).filter(Boolean)) {
      const nr = el('r'), nt = el('t'), pr = rPr ? rPr.cloneNode(true) : el('rPr');
      if (/^[☐☒]$/.test(piece)) { for (const old of all(pr, 'rFonts')) old.remove(); pr.prepend(el('rFonts', { ascii: 'Segoe UI Symbol', hAnsi: 'Segoe UI Symbol', eastAsia: 'Segoe UI Symbol', cs: 'Segoe UI Symbol' })); }
      nt.setAttributeNS(XML_NS, 'xml:space', 'preserve'); nt.textContent = piece; nr.append(pr, nt); r.parentNode.insertBefore(nr, r);
    }
    r.remove();
  }
  // Some browsers keep the XML declaration when serializing and some drop it; write exactly one.
  return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\\r\\n' + new XMLSerializer().serializeToString(doc).replace(/^<\\?xml[^>]*\\?>\\s*/, '');
}`]);

