ATL_SRC.push(['@atl/forms/email.js', 0, `// Builds an unsent email (.eml) that Outlook opens as a new message, ready to send — subject, body and attachments
// filled in. "X-Unsent: 1" is what makes Outlook open it as a draft instead of a received message.

const B64_LINE = 76;
/** Uint8Array → base64, wrapped at 76 characters (MIME). */
function b64(bytes) {
  let bin = '';
  for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(bin).replace(new RegExp(\`.{1,\${B64_LINE}}\`, 'g'), '$&\\r\\n');
}
const utf8b64 = s => b64(new TextEncoder().encode(s));
/** Header words outside plain ASCII use RFC 2047 encoded-words. */
const hdr = s => (/^[\\x20-\\x7e]*$/.test(s) ? s : \`=?UTF-8?B?\${utf8b64(s).replace(/\\s/g, '')}?=\`);
/** Attachment names: keep them plain ASCII so every mail client shows them the same. */
const asciiName = s => s.replace(/[–—]/g, '-').replace(/[^\\x20-\\x7e]/g, '').replace(/"/g, "'");

/** Email HTML → plain text for a mailto: body. Table rows on their own lines ("Field: value"), list items bulleted. */
export function mailText(html) {
  const marked = String(html || '').replace(/<(style|script|head)\\b[\\s\\S]*?<\\/\\1>/gi, '')
    .replace(/<br\\s*\\/?>/gi, '\\n').replace(/<li\\b[^>]*>/gi, '\\n• ').replace(/<\\/(tr|p|div|h\\d|table|ul|ol)>/gi, '\\n').replace(/<\\/t[dh]>/gi, '\\u0001');
  const text = new DOMParser().parseFromString(marked, 'text/html').body?.textContent || '';
  return text.split('\\n').map(l => {
    const cells = l.split('\\u0001').map(c => c.replace(/\\s+/g, ' ').trim()).filter(Boolean);
    return cells.length === 2 ? \`\${cells[0]}: \${cells[1]}\` : cells.join(' | ');
  }).join('\\n').replace(/\\n{3,}/g, '\\n\\n').trim();
}

// Windows passes a mailto: link to Outlook only up to about 2,000 characters, so a long body is shortened.
const MAILTO_MAX = 1900;

/** What to tell the user after an email with attachments (one message everywhere). */
export const DIRECT_TOAST = 'Outlook is opening with the email filled in — check it and press Send. The report was also saved to your Downloads folder: drag it into the email if you want it attached.';
export const EMAIL_TOAST ='Outlook draft downloaded — open it (click it in the browser’s downloads) and the email opens with the report attached, ready to send. Tip: choose “Always open files of this type” once and it opens in Outlook by itself.';

/**
 * Create the email. With attachments (Nov 2026, from Josh): a ready-to-send Outlook draft (.eml) is downloaded — To,
 * Subject, the full formatted message AND the files attached; opening it opens a new Outlook message (nothing is sent
 * until Send is pressed). A web page can't put files into an email through a mailto: link, so the draft is the way.
 * Without attachments: Outlook opens directly (mailto:) with To, Subject and the message text.
 * m: { to?, cc?, subject, html, attachments: [[fileName, Uint8Array, mimeType]], direct? }. Returns the attachment file names.
 * direct: true (Nov 2026, OTIF and call-off emails): Outlook opens right away (mailto:) with To, Subject and the message
 * text, and the attachments are saved to Downloads at the same time, to drag into the email if needed.
 */
export function openEmail(m) {
  if ((m.attachments || []).length && !m.direct) {
    const name = String(m.subject || 'Email').replace(/[\\\\/:*?"<>|]+/g, '-').replace(/\\s+/g, ' ').trim().slice(0, 120) + '.eml';
    const d = document.createElement('a');
    d.href = URL.createObjectURL(emlDraft(m)); d.download = name; d.click(); setTimeout(() => URL.revokeObjectURL(d.href), 4000);
    return m.attachments.map(([n]) => n);
  }
  return mailtoEmail(m);
}

/** Outlook opens directly via mailto: (To, Subject, message text — no attachments possible). */
function mailtoEmail(m) {
  const enc = s => encodeURIComponent(String(s).replace(/\\r?\\n/g, '\\r\\n'));
  const addr = s => String(s || '').split(/[;,]/).map(x => x.trim()).filter(Boolean).map(x => encodeURIComponent(x).replace(/%40/g, '@')).join(';');
  const files = (m.attachments || []).map(([name]) => name);
  const note = files.length ? \`\\n\\n[Attach: \${files.join(', ')} — saved to your Downloads folder]\` : '';
  const head = \`mailto:\${addr(m.to)}?\${m.cc ? \`cc=\${addr(m.cc)}&\` : ''}subject=\${enc(m.subject || '')}&body=\`;
  let body = mailText(m.html);
  const fits = b => (head + enc(b + note)).length <= MAILTO_MAX;
  if (!fits(body)) {
    const more = '\\n… (full details in the attached report)';
    let lo = 0, hi = body.length;
    while (lo < hi) { const mid = (lo + hi + 1) >> 1; if (fits(body.slice(0, mid) + more)) lo = mid; else hi = mid - 1; }
    const cut = body.slice(0, lo), nl = cut.lastIndexOf('\\n');
    body = (nl > 0 ? cut.slice(0, nl) : cut.replace(/\\s+\\S*$/, '')) + more; // end on a whole line
  }
  const a = document.createElement('a');
  a.href = head + enc(body + note);
  a.click();
  (m.attachments || []).forEach(([name, bytes, type], i) => setTimeout(() => {
    const d = document.createElement('a');
    d.href = URL.createObjectURL(new Blob([bytes], { type: type || 'application/octet-stream' }));
    d.download = name; d.click(); setTimeout(() => URL.revokeObjectURL(d.href), 2000);
  }, 500 + i * 350));
  return files;
}

/**
 * m: { to?, subject, html, attachments: [[fileName, Uint8Array, mimeType]] } → Blob (message/rfc822)
 */
export function emlDraft(m) {
  const list = s => String(s || '').split(/[;,]/).map(x => x.trim()).filter(Boolean).join(', '); // "a@x.com; b@y.com" → "a@x.com, b@y.com"
  const boundary = 'atl-ops-' + Math.random().toString(36).slice(2);
  const parts = [
    \`To: \${list(m.to)}\`,
    ...(m.cc ? [\`Cc: \${list(m.cc)}\`] : []),
    \`Subject: \${hdr(m.subject || '')}\`,
    'X-Unsent: 1',
    'MIME-Version: 1.0',
    \`Content-Type: multipart/mixed; boundary="\${boundary}"\`,
    '',
    \`--\${boundary}\`,
    'Content-Type: text/html; charset="utf-8"',
    'Content-Transfer-Encoding: base64',
    '',
    utf8b64(m.html),
  ];
  for (const [name, bytes, type] of m.attachments || []) {
    const n = asciiName(name);
    parts.push(\`--\${boundary}\`, \`Content-Type: \${type}; name="\${n}"\`, 'Content-Transfer-Encoding: base64',
      \`Content-Disposition: attachment; filename="\${n}"\`, '', b64(bytes));
  }
  parts.push(\`--\${boundary}--\`, '');
  return new Blob([parts.join('\\r\\n')], { type: 'message/rfc822' });
}`]);

