ATL_SRC.push(['@atl/sites.js', 0, `// Warehouse locations (Nov 2026, from Josh): the Atlanta buildings 6049 and 6021, plus 2900 Franklin Rd, 2222 Hillside,
// 3101 Columbus and Cincinnati. Each has its own dashboard, set up the same way. The list lives in Settings ▸ Locations
// (number, name, MHE site, manager, director; units come from each location's customers); a location without a number (Cincinnati, until it is typed in)
// is listed there only.
//
// Who sees what (Settings ▸ Users & access ▸ Locations): admins see every location. Everyone else sees only the
// locations ticked for them — one for a viewer, supervisor or manager, one or more for a director — and nothing
// recorded for any other location (dashboards, logs, MHE, safety, scorecards ...). The database enforces the same
// (firestore.rules ▸ canSee). A person with no locations set yet keeps the Atlanta buildings, as before this change.
import { store } from '@atl/store.js';
import { unitsAt, UNIT_WORD } from '@atl/throughput.js';

/** Combined = the Atlanta buildings (Josh: the new sites get their own dashboards only, no roll-up). */
export const ATL = ['6049', '6021'];
export const DEFAULT_SITES = [
  { id: '6049', name: 'Atlanta', mheSite: 'Fulton', manager: '', director: 'Josh Piper' },
  { id: '6021', name: 'Atlanta', mheSite: 'Greensboro', manager: '', director: 'Josh Piper' },
  { id: '2900', name: 'Franklin Rd', mheSite: 'Franklin Rd', manager: '', director: '' },
  { id: '2222', name: 'Hillside', mheSite: 'Hillside', manager: '', director: '' },
  { id: '3101', name: 'Columbus', mheSite: 'Columbus, IN', manager: '', director: '' },
  { id: '', name: 'Cincinnati', mheSite: 'Cincinnati, OH', manager: '', director: '' },
];
const clean = v => String(v ?? '').trim();

/** Every location in Settings (numbered or not), Atlanta first. */
export function siteList() {
  const saved = store.settings?.sites;
  const list = Array.isArray(saved) && saved.length ? saved : DEFAULT_SITES;
  return list.map(s => ({ ...s, id: clean(s.id), name: clean(s.name), mheSite: clean(s.mheSite) }));
}
/** Locations with a building number — the ones that have dashboards and data. */
export const sites = () => siteList().filter(s => s.id);
export const allIds = () => sites().map(s => s.id);
export const siteOf = id => sites().find(s => s.id === clean(id)) || null;
/** "2900 · Franklin Rd" (the Atlanta buildings: just the number). */
export const siteLabel = id => { const s = siteOf(id); return !s ? clean(id) : s.name && s.name !== 'Atlanta' ? \`\${s.id} · \${s.name}\` : s.id; };
/** A building's first unit (Nov 2026: units belong to its customers — Settings ▸ Throughput customers; a building can
 *  have several, see throughput.js ▸ unitsAt). 'Pallets' = skids, 'Tons' = rolls (tons). */
export const unitOf = id => unitsAt(String(id ?? '').trim())[0];
/** Every unit a building's customers are measured in. */
export const unitsOfSite = id => unitsAt(String(id ?? '').trim());
/** "skids" / "tons" / "bales, cartons" — the words for a building's units. */
export const unitWords = id => unitsOfSite(id).map(u => UNIT_WORD[u]).join(', ');
/** MHE: the register's site name (Fulton, Hillside ...) → building number, and back. */
export const bldgOfMheSite = name => sites().find(s => s.mheSite && s.mheSite === clean(name))?.id || '';
export const mheSiteOf = id => siteOf(id)?.mheSite || '';

// ---------- access ----------
/** Does the signed-in person see every location? (admins) */
export const seesAll = () => !!store.can?.('admin');
/** Building numbers the signed-in person may see. */
export function mySites() {
  if (seesAll()) return allIds();
  const mine = Array.isArray(store.sites) ? store.sites.map(clean) : ATL;
  return mine.filter(id => allIds().includes(id) || ATL.includes(id));
}
export const canSee = b => seesAll() || mySites().includes(clean(b));
/** Sees both Atlanta buildings (the Combined dashboard, the Atlanta customer scorecards). */
export const seesAtlanta = () => ATL.every(canSee);
/** One location for viewers, supervisors and managers; one or more for directors (admins: all). */
export const multiSite = role => role === 'director' || role === 'admin';`]);

